def backfill_zones(apps, schema_editor):
    """Accounts move from cashiers to zones; business days move to subzones;
    every transaction records its subzone."""
    Account = apps.get_model("core", "Account")
    CompanySim = apps.get_model("core", "CompanySim")
    CashierDay = apps.get_model("core", "CashierDay")
    User = apps.get_model("core", "User")
    users = {u.id: u for u in User.objects.all()}
    # SIMs: ordinary SIMs belong to their holder's subzone; the master SIM keeps its cashier in charge
    for sim in CompanySim.objects.all():
        if not sim.is_master and sim.custodian_id and users[sim.custodian_id].subzone_id:
            sim.subzone_id = users[sim.custodian_id].subzone_id
            sim.custodian_id = None
            sim.save(update_fields=["subzone", "custodian"])
    for a in Account.objects.filter(kind__in=["CASH_DRAWER", "UVE", "ER", "MTN"]).select_related("sim"):
        if a.sim_id and a.sim.is_master:
            a.zone_id = a.sim.master_zone_id
            a.custodian_id = a.sim.custodian_id
        elif a.sim_id and a.sim.subzone_id:
            a.zone_id, a.custodian_id = a.sim.subzone_id, None
        elif a.custodian_id and users[a.custodian_id].subzone_id:
            a.zone_id, a.custodian_id = users[a.custodian_id].subzone_id, None
        a.save(update_fields=["zone", "custodian"])
    # business days: one per subzone and date
    seen = {}
    with schema_editor.connection.cursor() as cur:
        cur.execute("SET LOCAL core.admin_override = 'on'")
        for d in CashierDay.objects.order_by("business_date", "-status", "id"):
            zid = users[d.cashier_id].subzone_id if d.cashier_id else None
            key = (zid, d.business_date)
            if key in seen and zid is not None:
                keep = seen[key]
                cur.execute("SELECT 1 FROM core_closing WHERE cashier_day_id = %s", [d.id])
                if cur.fetchone():
                    zid = None  # legacy duplicate closed day: keep it, without a zone
                else:
                    cur.execute("UPDATE core_transaction SET cashier_day_id = %s WHERE cashier_day_id = %s",
                                [keep, d.id])
                    cur.execute("DELETE FROM core_cashierday WHERE id = %s", [d.id])
                    continue
            else:
                seen[key] = d.id
            d.zone_id = zid
            d.save(update_fields=["zone"])
        # at most one open day per zone: older duplicates are closed
        for zid in set(z for z, _d in seen):
            if zid is None:
                continue
            opens = list(CashierDay.objects.filter(zone_id=zid, status="OPEN").order_by("-business_date"))
            for extra in opens[1:]:
                extra.status = "CLOSED"
                extra.save(update_fields=["status"])
        cur.execute("""
            UPDATE core_transaction t SET zone_id = d.zone_id
            FROM core_cashierday d WHERE t.cashier_day_id = d.id AND t.zone_id IS NULL
        """)
        cur.execute("""
            UPDATE core_transaction t SET zone_id = u.subzone_id
            FROM core_user u WHERE t.cashier_id = u.id AND t.zone_id IS NULL
        """)
        cur.execute("SET LOCAL core.admin_override = 'off'")


